#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from pathlib import Path
class ReportError(RuntimeError):pass
def load(path:Path):
 try:return json.loads(path.read_text(encoding="utf-8"))
 except (OSError,json.JSONDecodeError) as exc:raise ReportError(f"cannot load {path}: {exc}") from exc
def render(scores_path:Path,prices_path:Path,history_path:Path,output_dir:Path)->tuple[Path,Path]:
 scores=load(scores_path);prices=load(prices_path);history=load(history_path);dates={x.get("trade_date") for x in (scores,prices,history)}
 if len(dates)!=1:raise ReportError(f"input dates differ: {dates}")
 day=next(iter(dates));echarts_path=Path(__file__).resolve().parent.parent/"assets"/"echarts.min.js"
 try:echarts_js=echarts_path.read_text(encoding="utf-8").replace("</script","<\\/script")
 except OSError as exc:raise ReportError(f"cannot load {echarts_path}: {exc}") from exc
 bundle={"scores":scores,"prices":prices,"history":history};payload=json.dumps(bundle,ensure_ascii=False,separators=(",",":")).replace("</","<\\/")
 template=r"""<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>台股每日投本比報告 __DAY__</title><script>__ECHARTS__</script><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1220;color:#e5e7eb;font-family:system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:18px}.notice{padding:12px;margin:12px 0;border:1px solid #f59e0b;background:#422006;border-radius:9px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.card{background:#111827;padding:13px;border-radius:9px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}input,select,button{padding:8px;background:#1f2937;color:#fff;border:1px solid #64748b;border-radius:6px}.wrap{overflow:auto;background:#111827}table{border-collapse:collapse;width:100%;min-width:1450px}th,td{padding:8px;border-bottom:1px solid #334155;text-align:right;white-space:nowrap}th:nth-child(2),td:nth-child(2),th:nth-child(3),td:nth-child(3){text-align:left}th{background:#172033;position:sticky;top:0}.red{color:#fb7185}.green{color:#4ade80}.orange{color:#f59e0b}.chart{display:none;height:720px;margin:15px 0;background:#111827}.chart.open{display:block}details{max-width:360px;text-align:left;white-space:normal}.foot{margin-top:16px;padding:12px;border:1px solid #64748b}</style></head><body><main><h1>台股每日投信投本比與技術報告</h1><div class="foot">本報告僅供量化篩選、資訊整理與研究用途，不構成投資建議、買賣邀約或報酬保證。使用者應自行確認資料並承擔風險。</div><div class="notice">期間累計買超比例為估算，不是投信實際持股比例。線圖函式庫已內嵌，可離線顯示。<div id="warnings"></div></div><div class="cards"><div class="card">交易日<br><b>__DAY__</b></div><div class="card">候選<br><b id="candidateCount"></b></div><div class="card">強勢候選<br><b id="strongCount"></b></div><div class="card">可觀察<br><b id="watchCount"></b></div></div><div class="filters"><input id="q" placeholder="代號或名稱"><input id="min" type="number" value="0" min="0" max="100" placeholder="最低分"><select id="mode"><option value="">全部模式</option><option value="conservative">穩健</option><option value="aggressive">激進</option></select><select id="rating"><option value="">全部評級</option><option>強勢候選</option><option>可觀察</option><option>條件不足</option><option>不列入</option></select><button onclick="drawTable()">篩選</button></div><div class="wrap"><table><thead><tr><th>#</th><th>代號</th><th>名稱</th><th>分數</th><th>評級</th><th>模式</th><th>投本比%</th><th>全市場排名</th><th>連買日</th><th>近3日投信張</th><th>近3日外資張</th><th>量張</th><th>資本額億</th><th>分項原因</th><th>線圖</th></tr></thead><tbody id="rows"></tbody></table></div><div id="charts"></div><div class="foot">本報告僅供量化研究，不構成投資建議。歷史行情、法人籌碼及技術訊號不保證未來結果。</div></main><script>const D=__DATA__;const S=D.scores.records;const P=new Map(D.prices.records.map(x=>[x.stock_code,x]));const H=new Map(D.history.records.map(x=>[x.stock_code,x]));const esc=x=>String(x??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));const fmt=(x,n=2)=>Number(x).toLocaleString("zh-TW",{maximumFractionDigits:n});document.querySelector("#candidateCount").textContent=S.length;document.querySelector("#strongCount").textContent=D.scores.counts.strong;document.querySelector("#watchCount").textContent=D.scores.counts.watch;document.querySelector("#warnings").innerHTML=(D.scores.warnings||[]).map(x=>"<div>⚠ "+esc(x)+"</div>").join("");function drawTable(){const q=document.querySelector("#q").value.trim().toLowerCase(),min=Number(document.querySelector("#min").value||0),mode=document.querySelector("#mode").value,rating=document.querySelector("#rating").value;const list=S.filter(x=>(!q||(x.stock_code+x.stock_name).toLowerCase().includes(q))&&x.total_score>=min&&(!rating||x.rating===rating)&&(!mode||(mode==="conservative"?x.conservative_passed:x.aggressive_passed)));document.querySelector("#rows").innerHTML=list.map((x,i)=>{const modes=x.conservative_passed?"穩健、激進":"激進",sections=Object.entries(x.sections).map(([k,v])=>k+" "+v.score+"/"+v.max+"："+v.reasons.join("、")).join("｜");return "<tr><td>"+(i+1)+"</td><td>"+esc(x.stock_code)+"</td><td>"+esc(x.stock_name)+"</td><td><b>"+x.total_score+"</b></td><td>"+esc(x.rating)+"</td><td>"+modes+"</td><td>"+fmt(x.investment_ratio_pct,4)+"</td><td>"+x.positive_ratio_rank+"</td><td>"+x.sitc_buy_streak+"</td><td class=\""+(x.sitc_net_shares_3d_sum>=0?"red":"green")+"\">"+fmt(x.sitc_net_shares_3d_sum/1000)+"</td><td class=\""+(x.foreign_net_shares_3d_sum>=0?"red":"green")+"\">"+fmt(x.foreign_net_shares_3d_sum/1000)+"</td><td>"+fmt(x.volume_lots)+"</td><td>"+fmt(x.paid_in_capital_twd/1e8)+"</td><td><details><summary>查看</summary>"+esc(sections)+"</details></td><td>"+(P.has(x.stock_code)?"<button type=\"button\" class=\"chart-toggle\" data-code=\""+esc(x.stock_code)+"\">展開</button>":"<span class=\"orange\">無技術圖</span>")+"</td></tr>"}).join("")}drawTable();document.querySelector("tbody").addEventListener("click",event=>{const button=event.target.closest(".chart-toggle");if(button)toggleChart(button.dataset.code)});function sma(a,n){return a.map((_,i)=>i<n-1?null:a.slice(i-n+1,i+1).reduce((s,v)=>s+v,0)/n)}function toggleChart(code){let box=document.querySelector("#chart-"+code);if(!box){box=document.createElement("div");box.id="chart-"+code;box.className="chart";document.querySelector("#charts").appendChild(box)}box.classList.toggle("open");if(!box.classList.contains("open"))return;box.scrollIntoView({behavior:"smooth",block:"start"});if(typeof echarts==="undefined"){box.textContent="線圖函式庫載入失敗，請確認網路連線後重新整理頁面";return}const item=P.get(code),hist=H.get(code);if(!item||!hist){box.textContent="技術或法人歷史資料缺失";return}const p=item.ohlcv_history,h=hist.sitc_history,hm=new Map(h.map(x=>[x.trade_date,x])),dates=p.map(x=>x.trade_date),close=p.map(x=>+x.close),k=p.map(x=>[+x.open,+x.close,+x.low,+x.high]),vol=p.map(x=>x.volume_shares/1000),sitc=dates.map(d=>(hm.get(d)?.sitc_net_shares??null)/1000),foreign=dates.map(d=>(hm.get(d)?.foreign_net_shares??null)/1000),chart=echarts.init(box);chart.setOption({animation:false,title:{text:code+" "+item.stock_name,textStyle:{color:"#fff"}},legend:{data:["K線","MA5","MA10","MA20","成交量","投信","外資"],textStyle:{color:"#ddd"}},tooltip:{trigger:"axis",axisPointer:{type:"cross"}},axisPointer:{link:[{xAxisIndex:"all"}]},grid:[{left:60,right:30,top:55,height:"48%"},{left:60,right:30,top:"60%",height:"14%"},{left:60,right:30,top:"79%",height:"15%"}],xAxis:[{type:"category",data:dates,axisLabel:{show:false}},{type:"category",gridIndex:1,data:dates,axisLabel:{show:false}},{type:"category",gridIndex:2,data:dates}],yAxis:[{scale:true},{scale:true,gridIndex:1,name:"張"},{scale:true,gridIndex:2,name:"張"}],dataZoom:[{type:"inside",xAxisIndex:[0,1,2],start:45,end:100},{type:"slider",xAxisIndex:[0,1,2],bottom:5,start:45,end:100}],series:[{name:"K線",type:"candlestick",data:k,itemStyle:{color:"#ef4444",color0:"#22c55e",borderColor:"#ef4444",borderColor0:"#22c55e"}},{name:"MA5",type:"line",data:sma(close,5),showSymbol:false},{name:"MA10",type:"line",data:sma(close,10),showSymbol:false},{name:"MA20",type:"line",data:sma(close,20),showSymbol:false},{name:"成交量",type:"bar",xAxisIndex:1,yAxisIndex:1,data:vol},{name:"投信",type:"bar",xAxisIndex:2,yAxisIndex:2,data:sitc,itemStyle:{color:p=>p.value>=0?"#ef4444":"#22c55e"}},{name:"外資",type:"bar",xAxisIndex:2,yAxisIndex:2,data:foreign,itemStyle:{color:p=>p.value>=0?"#fb7185":"#4ade80"}}]});window.addEventListener("resize",()=>chart.resize(),{once:true})}</script></body></html>"""
 html=template.replace("__DAY__",day).replace("__DATA__",payload).replace("__ECHARTS__",echarts_js);stamp=day.replace("-","");output_dir.mkdir(parents=True,exist_ok=True);dated=output_dir/f"tw_stock_momentum_report_{stamp}.html";latest=output_dir/"latest.html";dated.write_text(html,encoding="utf-8");latest.write_text(html,encoding="utf-8");data_dir=output_dir/"data";data_dir.mkdir(parents=True,exist_ok=True);(data_dir/f"report_{stamp}.json").write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+"\n",encoding="utf-8");return latest,dated
def main()->int:
 p=argparse.ArgumentParser();p.add_argument("--scores",type=Path,required=True);p.add_argument("--prices",type=Path,required=True);p.add_argument("--history",type=Path,required=True);p.add_argument("--output-dir",type=Path,required=True);a=p.parse_args();latest,dated=render(a.scores,a.prices,a.history,a.output_dir);print(f"wrote {latest} and {dated}");return 0
if __name__=="__main__":
 try:raise SystemExit(main())
 except ReportError as exc:print(f"ERROR: {exc}",file=__import__("sys").stderr);raise SystemExit(2)
